local ECSComponent = import("Frame.ECS.ECSComponent")

---@class PetComponent
local PetComponent = Class('PetComponent', ECSComponent)

local PetDojo = import("Game.Dojo.PetDojo")

function PetComponent:__init()
    --
    ---@type PetDojo[]
    self.Pets = nil
end

function PetComponent:__delete()
    --
    self.Pets = nil

end

function PetComponent:FillData(jsonStr)
    local datas = nil
    if type(jsonStr) == 'string' then
        datas = table.deserialize(jsonStr)
    else
        datas = checkTable(jsonStr)
    end

    self.Pets = {}

    for k,v in pairs(datas) do
        if k == "pets" then
            for i = 1, #v do
                ---@type PetDojo
                local dojo = PetDojo.New()
                dojo:Fill(v[i])

                table.insert(self.Pets, dojo)
            end

        end
    end
end

---@return PetDojo
function PetComponent:GetPetById(id)
    local pet = nil
    if self.Pets == nil then
        return pet
    end
    for i = 1, #self.Pets do
        if self.Pets[i].petId == id then
            pet = self.Pets[i]
            break
        end
    end
    return pet
end

function PetComponent:UnlockPetSuit(id, customSuit)
    local pet = self:GetPetById(id)
    if pet == nil then
        printError("%d cant found", id)
        return
    end
    pet:UnlockSuit(customSuit)
end

function PetComponent:AddPetSuit(id, customSuit, name, parts)
    local pet = self:GetPetById(id)
    if pet == nil then
        printError("%d cant found", id)
        return
    end
    pet:AddSuit(customSuit, name, parts)
end

function PetComponent:SetPetMood(id, mood)
    local pet = self:GetPetById(id)
    if pet == nil then
        printError("%d cant found", id)
        return
    end
    pet.mood = mood
end

function PetComponent:WearPetSuit(id, suitType, suitId)
    local pet = self:GetPetById(id)
    if pet == nil then
        printError("%d cant found", id)
        return
    end
    pet.wearingSuitId = suitId
    pet.wearingSuitType = suitType
end

return PetComponent